-- Statements that reach node kinds the documentation corpus rarely uses:
-- keyword functions, GROUPING SETS, JSON and XML functions. Same record
-- format as postgres_doc.sql.
;;
SELECT a, sum(b) FROM t GROUP BY ROLLUP (a, b);
;;
SELECT a, sum(b) FROM t GROUP BY CUBE (a, b);
;;
SELECT a, sum(b) FROM t GROUP BY GROUPING SETS ((a), (b), ());
;;
SELECT a FROM t GROUP BY ();
;;
SELECT a FROM t GROUP BY DISTINCT a, b;
;;
SELECT a COLLATE "C" FROM t;
;;
SELECT ts AT TIME ZONE 'UTC' FROM t;
;;
SELECT ts AT LOCAL FROM t;
;;
SELECT a IS DISTINCT FROM b FROM t;
;;
SELECT a BETWEEN SYMMETRIC 1 AND 2 FROM t;
;;
SELECT (a, b) OVERLAPS (c, d) FROM t;
;;
SELECT arr[1:2], arr[:3], arr[2:] FROM t;
;;
SELECT (row_val).f, (t.c).* FROM t;
;;
SELECT EXISTS (SELECT 1) FROM t;
;;
SELECT a = ANY (SELECT b FROM u) FROM t;
;;
SELECT a = ANY (ARRAY[1, 2]) FROM t;
;;
SELECT string_agg(a, ',' ORDER BY a DESC) FROM t;
;;
SELECT count(*) FILTER (WHERE a > 1) FROM t;
;;
SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY a) FROM t;
;;
SELECT row_number() OVER (PARTITION BY a ORDER BY b ROWS BETWEEN 1 PRECEDING AND CURRENT ROW EXCLUDE TIES) FROM t;
;;
SELECT sum(a) OVER w FROM t WINDOW w AS (ORDER BY b);
;;
SELECT concat_ws(',', VARIADIC ARRAY['a', 'b']);
;;
SELECT count(DISTINCT a) FROM t;
;;
SELECT count(ALL a) FROM t;
;;
SELECT EXTRACT(YEAR FROM ts) FROM t;
;;
SELECT POSITION('a' IN 'abc');
;;
SELECT SUBSTRING('abc' FROM 2 FOR 1);
;;
SELECT SUBSTRING('abc' SIMILAR 'a' ESCAPE '#');
