WITH RECURSIVE x(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM x) SEARCH DEPTH FIRST BY n SET ord CYCLE n SET c USING p SELECT * FROM x;
;;
WITH x AS MATERIALIZED (SELECT 1), y AS NOT MATERIALIZED (SELECT 2) SELECT 1;
;;
TABLE t;
;;
VALUES (1, DEFAULT), (2, 3);
;;
INSERT INTO t (a, b[1], c.d) OVERRIDING SYSTEM VALUE VALUES (1, 2, 3) ON CONFLICT (a COLLATE "C" text_ops) WHERE a > 0 DO UPDATE SET b = EXCLUDED.b WHERE t.b <> 1 RETURNING *;
;;
INSERT INTO t AS x DEFAULT VALUES RETURNING OLD.a, NEW.a;
;;
INSERT INTO t VALUES (1) ON CONFLICT ON CONSTRAINT c DO NOTHING;
;;
UPDATE t SET (a, b) = (SELECT 1, 2), c = DEFAULT, d[1] = 3 WHERE CURRENT OF cur;
;;
UPDATE ONLY t * AS x SET a = 1 RETURNING WITH (OLD AS o) o.a;
;;
DELETE FROM t WHERE a IN (1) RETURNING *;
;;
MERGE INTO t USING s ON t.a = s.a WHEN MATCHED AND s.x THEN UPDATE SET b = s.b WHEN NOT MATCHED BY SOURCE THEN DELETE WHEN NOT MATCHED THEN INSERT (a) OVERRIDING USER VALUE VALUES (s.a) RETURNING merge_action(), *;
;;
